cli_help.stdout:
usage: aqef contract [-h] {create,get,list,update} ...

positional arguments:
  {create,get,list,update}
    create              POST /projects/{project}/contracts
    get                 GET /projects/{project}/contracts/{contract}
    list                GET /projects/{project}/contracts
    update              PUT /projects/{project}/contracts/{contract}

options:
  -h, --help            show this help message and exit

usage: aqef environment [-h] {create,delete,get,list,update} ...

positional arguments:
  {create,delete,get,list,update}
    create              POST /projects/{project}/environments
    delete              DELETE /projects/{project}/environments/{env}
    get                 GET /projects/{project}/environments/{env}
    list                GET /projects/{project}/environments
    update              PUT /projects/{project}/environments/{env}

options:
  -h, --help            show this help message and exit

usage: aqef project [-h] {delete,get,list,load,update} ...

positional arguments:
  {delete,get,list,load,update}
    delete              DELETE /projects/{project}
    get                 GET /projects/{project}
    list                GET /projects
    load                POST /projects
    update              PUT /projects/{project}

options:
  -h, --help            show this help message and exit

usage: aqef scenario [-h] {create,delete,get,update} ...

positional arguments:
  {create,delete,get,update}
    create              POST /projects/{project}/suites/{suite}/scenarios
    delete              DELETE /projects/{project}/suites/{suite}/scenarios/{s
                        cenario}
    get                 GET /projects/{project}/suites/{suite}/scenarios/{scen
                        ario}
    update              PUT /projects/{project}/suites/{suite}/scenarios/{scen
                        ario}

options:
  -h, --help            show this help message and exit

